{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Tocotrienol-rich palm oil has poor oral bioavailability in humans; tocotrienol shares a lipophilic isoprenoid side chain and redox-active ring with the ubiquinone query, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Lycopene from tomato paste showed only 0.17% systemic availability in humans, illustrating the poor absorption of a highly lipophilic isoprenoid lipid analogous to the query's long polyisoprenoid tail.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Synthetic lycopene dispersed in oil gave about 1.2% systemic availability in humans, showing that even oil-formulated lipophilic isoprenoids can remain poorly absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Deuterated lycopene bioavailability was estimated at 1.2% in humans, independently reinforcing low absorption for this lipophilic isoprenoid class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Phytoene showed 58.5% absolute bioavailability in humans, providing a contradictory example that some long-chain isoprenoid lipids can be well absorbed, though phytoene lacks the quinone head of the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "All-trans lycopene reached 23.2% bioavailability in one human study, a borderline contradictory result above the 20% threshold, but it is formulation- and matrix-dependent.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low oral bioavailability (<20%) for the ubiquinone-9 query, based on the poor absorption of related lipophilic isoprenoid lipids (tocotrienol, lycopene) and the known poor bioavailability of ubiquinones; high phytoene values are less transferable because the query has a polar quinone head and very long lipophilic tail.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for ubiquinone-9 (CoQ9) is provided.",
    "No intravenous comparator data for the query or a close ubiquinone analogue are available.",
    "Formulation, food matrix, and dose effects are not specified for the query, and these strongly modulate lipophilic compound absorption."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

